t.script:
document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('register-form');
    const messageContainer = document.getElementById('message-container');
    const submitBtn = document.getElementById('submit-btn');
    const btnText = document.getElementById('btn-text');
    const btnSpinner = document.getElementById('btn-spinner');

    form.addEventListener('submit', async function(e) {
        e.preventDefault();

        // Limpiar mensajes anteriores
        messageContainer.innerHTML = '';

        // Obtener valores del formulario
        const name = document.getElementById('register_name').value.trim();
        const login = document.getElementById('register_email').value.trim();
        const password = document.getElementById('register_password').value;
        const confirmPassword = document.getElementById('register_password_confirm').value;

        // Validar que las contraseñas coincidan
        if (password !== confirmPassword) {
            showMessage('Las contraseñas no coinciden', 'danger');
            return;
        }

        // Validar longitud de contraseña
        if (password.length < 6) {
            showMessage('La contraseña debe tener al menos 6 caracteres', 'danger');
            return;
        }

        // Deshabilitar botón y mostrar spinner
        submitBtn.disabled = true;
        btnText.textContent = 'Creando cuenta...';
        btnSpinner.classList.remove('d-none');

        try {
            const response = await fetch('/api/auth/register', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    name: name,
                    login: login,
                    password: password
                })
            });

            const data = await response.json();

            if (response.ok) {
                showMessage('¡Cuenta creada exitosamente! Redirigiendo...', 'success');
                form.reset();

                // Redirigir a la página de suscripción exitosa
                setTimeout(() => {
                    window.location.href = '/subscription-success';
                }, 1500);
            } else {
                const errorMsg = data.error || 'Error al crear la cuenta. Por favor, intenta nuevamente.';
                showMessage(errorMsg, 'danger');
            }
        } catch (error) {
            console.error('Error:', error);
            showMessage('Error de conexión. Por favor, verifica tu conexión a internet.', 'danger');
        } finally {
            // Rehabilitar botón y ocultar spinner
            submitBtn.disabled = false;
            btnText.textContent = 'Registrarse';
            btnSpinner.classList.add('d-none');
        }
    });

    function showMessage(message, type) {
        const alertDiv = document.createElement('div');
        alertDiv.className = `alert alert-${type} alert-dismissible fade show`;
        alertDiv.role = 'alert';
        alertDiv.innerHTML = `
            ${message}
            <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
        `;
        messageContainer.appendChild(alertDiv);

        // Auto-cerrar después de 5 segundos para mensajes de éxito
        if (type === 'success') {
            setTimeout(() => {
                alertDiv.remove();
            }, 5000);
        }
    }
});
